<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\CitizenComplaint;use App\Models\Station;use Illuminate\Http\Request;
class ComplaintController extends Controller {public function index(Request $r){$complaints=CitizenComplaint::with(['station','caseFir'])->when($r->filled('search'),fn($q)=>$q->where(fn($q)=>$q->where('complainant_name','like','%'.$r->search.'%')->orWhere('complainant_nid','like','%'.$r->search.'%')->orWhere('description','like','%'.$r->search.'%')))->when($r->filled('status'),fn($q)=>$q->whereRaw('LOWER(status)=?',[strtolower($r->status)]))->when($r->filled('station_id'),fn($q)=>$q->where('station_id',$r->station_id))->orderByDesc('submitted_date')->paginate(15)->withQueryString();foreach($complaints as $c){$c->station_name=$c->station?->name;$c->case_id=$c->caseFir?->case_id;}$stations=Station::orderBy('name')->get();$statuses=CitizenComplaint::select('status')->distinct()->orderBy('status')->get();return view('admin.complaints',compact('complaints','stations','statuses'));}}
